      "achados": [
        {
          "proposicao": "Modelos simplificados por balanço de massa são apresentados como úteis para análise mais geral do separador, mas com perda de detalhes que podem passar despercebidos na simulação.",
          "trechos": [
            "E61bd68e4640c5df4:0:700"
