          ]
        },
        {
          "proposicao": "A possibilidade de desenvolver modelos em diagramas de blocos é apresentada como alternativa interessante para ajuste e desenvolvimento de sistemas de controle.",
          "trechos": [
            "E61bd68e4640c5df4:0:700",
