          ]
        },
        {
          "proposicao": "A fonte recomenda atenção à sintonia das malhas de controle, associando-a à segurança da operação, à otimização da separação e à prevenção de paradas não programadas, além de indicar que o controle do separador pode afetar a qualidade do óleo e da água de saída.",
          "trechos": [
            "E61bd68e4640c5df4:700:1399",
            "E61bd68e4640c5df4:1399:2094"
          ],
          "condicoes": [
            "existência de malhas de controle no separador"
          ],
          "limites": [
            "o texto não informa quais malhas, variáveis ou critérios de sintonia",
            "por ser recomendação de trabalho e discussão, não constitui norma nem prova empírica geral"
          ]
        }
      ]
    },
    {
