      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Grande agitação e cisalhamento são associados à dispersão da fase oleosa na aquosa e à formação de emulsões, relacionando condições hidrodinâmicas internas com dificuldade de separação.",
          "trechos": [
            "Eff03b0b779b9d601:0:698"
          ],
          "condicoes": [
            "presença de agitação e cisalhamento elevados"
          ],
          "limites": [
